defmodule Astraea.External.FofPrinter do
  @moduledoc """
  Prints `Astraea.Arena` clause sets as untyped TPTP FOF problems for provers
  without TFF support, via `Astraea.External.FolEncoding` and the type guards of
  `Astraea.External.TypeEncoding` (Leo-III's `MonoGuards` / `MonoGuardsLight`).

  The higher-order to first-order step is the same as for
  `Astraea.External.TffPrinter`; sorts are then erased and soundness is kept by
  guard predicates `astraea_is_<type>` on the sorts that need them, with typing
  axioms `ty<k>`. Clause `i` is named `c<i>`, definitions `d<k>`.
  """

  alias Astraea.{Arena, ProofChecker}
  alias Astraea.External.{FolEncoding, TffPrinter, TypeEncoding}

  @doc """
  Renders `clauses` as a FOF problem. Options:
    * `:encoding` - first-order encoding; when it does not set `:types`, it is
      `:mono_guards_light`. `types: :mono_native` is rejected.
    * `:role`, `:name_prefix` - as for `Astraea.External.TffPrinter.problem/3`

  Raises `ArgumentError` on invalid encodings.
  """
  @spec problem(Arena.t(), [ProofChecker.clause()], keyword()) :: String.t()
  def problem(%Arena{} = arena, clauses, opts \\ []) do
    enc = encoding(Keyword.get(opts, :encoding))

    if enc[:types] == :mono_native do
      raise ArgumentError, "FOF output needs a guard type encoding, got types: :mono_native"
    end

    arena
    |> FolEncoding.encode(clauses, Keyword.put(opts, :encoding, enc))
    |> render()
  end

  @doc """
  Normalizes `encoding` for FOF output: `:types` defaults to `:mono_guards_light`.
  """
  @spec encoding(nil | atom() | keyword()) :: FolEncoding.t()
  def encoding(nil), do: FolEncoding.normalize!(types: :mono_guards_light)

  def encoding(preset) when is_atom(preset),
    do: FolEncoding.normalize!(base: preset, types: :mono_guards_light)

  def encoding(opts) when is_list(opts),
    do: FolEncoding.normalize!(Keyword.put_new(opts, :types, :mono_guards_light))

  def encoding(other), do: FolEncoding.normalize!(other)

  @doc """
  Renders an encoded `Astraea.External.FolEncoding.Problem` as guarded FOF.
  """
  @spec render(FolEncoding.Problem.t()) :: String.t()
  def render(%FolEncoding.Problem{} = problem) do
    guarded = TypeEncoding.guarded_sorts(problem, problem.encoding[:types])
    binder = binder(guarded)

    typing =
      problem
      |> TypeEncoding.axioms(guarded)
      |> Enum.with_index(fn f, k -> %{name: "ty#{k}", role: "axiom", formula: f} end)

    IO.iodata_to_binary([
      "% Generated by Astraea.External.FofPrinter (",
      TffPrinter.describe(problem.encoding),
      ")\n",
      guarded_comment(problem.arena, guarded),
      Enum.map(problem.formulas ++ typing, fn %{name: name, role: role, formula: f} ->
        ["fof(", name, ", ", role, ", ", FolEncoding.render_formula(f, binder), ").\n"]
      end)
    ])
  end

  # Universal quantifiers are relativized to the guards of their guarded variables.
  # Existential ones occur only in the inhabitation axioms, which are guards already.
  defp binder(guarded) do
    fn
      :exists, vars, body ->
        ["(? [", Enum.map_intersperse(vars, ", ", &elem(&1, 0)), "]: ", body, ")"]

      :all, vars, body ->
        names = Enum.map_intersperse(vars, ", ", &elem(&1, 0))

        guards =
          for {name, ty} <- vars, MapSet.member?(guarded, ty) do
            [TypeEncoding.guard_name(ty), "(", name, ")"]
          end

        case guards do
          [] -> ["(! [", names, "]: ", body, ")"]
          _ -> ["(! [", names, "]: ((", Enum.intersperse(guards, " & "), ") => ", body, "))"]
        end
    end
  end

  defp guarded_comment(arena, guarded) do
    Enum.map(Enum.sort(guarded), fn ty ->
      ["% ", TypeEncoding.guard_name(ty), " guards sort ", FolEncoding.sort(arena, ty), "\n"]
    end)
  end
end
